-- Phase 4: repair jobs, status history, notes, labour, quotations and idempotency keys.
-- Hand-written sections are marked "Hand-written"; the rest is generated by Prisma.

-- Hand-written: repair references come from a sequence (unique, never reused, safe
-- under concurrent inserts), widening past six digits instead of truncating.
CREATE SEQUENCE "repair_reference_seq";

CREATE FUNCTION next_repair_reference() RETURNS text LANGUAGE sql VOLATILE AS $$
  SELECT 'RJ-' || lpad(n::text, greatest(6, length(n::text)), '0')
  FROM (SELECT nextval('repair_reference_seq') AS n) s
$$;

