CREATE TYPE "RepairStatus" AS ENUM ('SUBMITTED', 'ASSIGNED', 'DIAGNOSING', 'AWAITING_APPROVAL', 'APPROVED', 'QUOTE_REJECTED', 'IN_REPAIR', 'AWAITING_PARTS', 'QUALITY_CHECK', 'COMPLETED', 'CLOSED', 'RETURNED_UNREPAIRED', 'CANCELLED');

-- CreateEnum
CREATE TYPE "RepairSource" AS ENUM ('STAFF', 'PORTAL');

-- CreateEnum
CREATE TYPE "RepairNoteType" AS ENUM ('FAULT', 'DIAGNOSTIC', 'REPAIR', 'INTERNAL', 'CUSTOMER_VISIBLE');

-- CreateEnum
CREATE TYPE "QuotationStatus" AS ENUM ('DRAFT', 'ISSUED', 'APPROVED', 'REJECTED', 'SUPERSEDED', 'WITHDRAWN');

-- CreateEnum
CREATE TYPE "DecisionChannel" AS ENUM ('PORTAL', 'PHONE', 'IN_PERSON', 'EMAIL');

-- CreateEnum
CREATE TYPE "QuotationLineKind" AS ENUM ('LABOUR', 'PART', 'OTHER');

