-- Hand-written: constraints and guards Prisma cannot express.

-- A device has at most one open repair job. COMPLETED still counts as open: the
-- device has not been handed back yet. This also stops a double-submitted request
-- from opening two jobs for the same device.
CREATE UNIQUE INDEX "repair_jobs_one_open_per_asset_idx" ON "repair_jobs" ("asset_id")
  WHERE "status" NOT IN ('CLOSED', 'RETURNED_UNREPAIRED', 'CANCELLED');

-- Every job past SUBMITTED has a technician (a job cancelled straight from SUBMITTED may not).
ALTER TABLE "repair_jobs" ADD CONSTRAINT "repair_jobs_technician_chk"
  CHECK ("status" IN ('SUBMITTED', 'CANCELLED') OR "assigned_technician_id" IS NOT NULL);

-- A job cannot be completed without a completion summary.
ALTER TABLE "repair_jobs" ADD CONSTRAINT "repair_jobs_completion_chk"
  CHECK ("status" NOT IN ('COMPLETED', 'CLOSED') OR ("completion_summary" IS NOT NULL AND "completed_at" IS NOT NULL));

-- Finished jobs record when they finished.
ALTER TABLE "repair_jobs" ADD CONSTRAINT "repair_jobs_closed_at_chk"
  CHECK (("status" IN ('CLOSED', 'RETURNED_UNREPAIRED', 'CANCELLED')) = ("closed_at" IS NOT NULL));

ALTER TABLE "labour_entries" ADD CONSTRAINT "labour_entries_minutes_chk"
  CHECK ("minutes" BETWEEN 1 AND 1440);

-- Money is never negative, totals add up, and revisions start at 1.
ALTER TABLE "quotations" ADD CONSTRAINT "quotations_money_chk"
  CHECK ("subtotal_cents" >= 0 AND "vat_cents" >= 0 AND "total_cents" = "subtotal_cents" + "vat_cents"
         AND "vat_rate_basis_points" BETWEEN 0 AND 10000 AND "revision" >= 1);

-- An issued (or later) quotation records who issued it and when.
ALTER TABLE "quotations" ADD CONSTRAINT "quotations_issued_chk"
  CHECK ("status" = 'DRAFT' OR ("issued_at" IS NOT NULL AND "issued_by_id" IS NOT NULL));

-- An approval or rejection records who decided, when and through which channel.
ALTER TABLE "quotations" ADD CONSTRAINT "quotations_decided_chk"
  CHECK ("status" NOT IN ('APPROVED', 'REJECTED')
         OR ("decided_by_id" IS NOT NULL AND "decided_at" IS NOT NULL AND "decision_channel" IS NOT NULL));

-- An approval stores the exact total that was approved, and only approvals do.
ALTER TABLE "quotations" ADD CONSTRAINT "quotations_approved_chk"
  CHECK (("status" = 'APPROVED') = ("approved_total_cents" IS NOT NULL)
         AND ("approved_total_cents" IS NULL OR "approved_total_cents" = "total_cents"));

-- At most one issued quotation and one draft per repair job at a time.
CREATE UNIQUE INDEX "quotations_one_issued_per_job_idx" ON "quotations" ("repair_job_id") WHERE "status" = 'ISSUED';
CREATE UNIQUE INDEX "quotations_one_draft_per_job_idx" ON "quotations" ("repair_job_id") WHERE "status" = 'DRAFT';

ALTER TABLE "quotation_lines" ADD CONSTRAINT "quotation_lines_values_chk"
  CHECK ("quantity_hundredths" > 0 AND "unit_price_cents" >= 0 AND "line_total_cents" >= 0 AND "position" >= 1);

-- Issued quotations are immutable. Only a DRAFT may change; an ISSUED quotation may
-- only move to a decision (or be superseded or withdrawn) and record that decision;
-- after that nothing changes. A DRAFT is the only quotation that can be deleted.
CREATE FUNCTION "quotations_guard"() RETURNS trigger AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD."status" <> 'DRAFT' THEN
      RAISE EXCEPTION 'quotation % is % and cannot be deleted', OLD."id", OLD."status";
    END IF;
    RETURN OLD;
  END IF;

  IF OLD."status" = 'DRAFT' THEN
    RETURN NEW;
  END IF;

  IF NEW."status" = 'DRAFT'
     OR NEW."repair_job_id" <> OLD."repair_job_id"
     OR NEW."revision" <> OLD."revision"
     OR NEW."currency" <> OLD."currency"
     OR NEW."vat_rate_basis_points" <> OLD."vat_rate_basis_points"
     OR NEW."subtotal_cents" <> OLD."subtotal_cents"
     OR NEW."vat_cents" <> OLD."vat_cents"
     OR NEW."total_cents" <> OLD."total_cents"
     OR NEW."customer_note" IS DISTINCT FROM OLD."customer_note"
     OR NEW."created_by_id" <> OLD."created_by_id"
     OR NEW."issued_by_id" IS DISTINCT FROM OLD."issued_by_id"
     OR NEW."issued_at" IS DISTINCT FROM OLD."issued_at" THEN
    RAISE EXCEPTION 'quotation % is % and its contents cannot change', OLD."id", OLD."status";
  END IF;

  IF OLD."status" <> 'ISSUED' AND (
       NEW."status" <> OLD."status"
       OR NEW."decided_by_id" IS DISTINCT FROM OLD."decided_by_id"
       OR NEW."decided_at" IS DISTINCT FROM OLD."decided_at"
       OR NEW."decision_channel" IS DISTINCT FROM OLD."decision_channel"
       OR NEW."decision_note" IS DISTINCT FROM OLD."decision_note"
       OR NEW."approved_total_cents" IS DISTINCT FROM OLD."approved_total_cents") THEN
    RAISE EXCEPTION 'quotation % is already %', OLD."id", OLD."status";
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER "quotations_guard"
  BEFORE UPDATE OR DELETE ON "quotations"
  FOR EACH ROW EXECUTE FUNCTION "quotations_guard"();

-- Lines can only be added, changed or removed while their quotation is a DRAFT.
-- (When a draft is deleted, its lines are removed by the cascade after the parent
-- row is gone, so a missing parent is allowed.)
CREATE FUNCTION "quotation_lines_guard"() RETURNS trigger AS $$
DECLARE
  parent_status "QuotationStatus";
BEGIN
  IF TG_OP IN ('UPDATE', 'DELETE') THEN
    SELECT "status" INTO parent_status FROM "quotations" WHERE "id" = OLD."quotation_id";
    IF parent_status IS NOT NULL AND parent_status <> 'DRAFT' THEN
      RAISE EXCEPTION 'lines of a % quotation cannot change', parent_status;
    END IF;
  END IF;
  IF TG_OP IN ('INSERT', 'UPDATE') THEN
    SELECT "status" INTO parent_status FROM "quotations" WHERE "id" = NEW."quotation_id";
    IF parent_status IS DISTINCT FROM 'DRAFT' THEN
      RAISE EXCEPTION 'lines can only be added to a draft quotation';
    END IF;
    RETURN NEW;
  END IF;
  RETURN OLD;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER "quotation_lines_guard"
  BEFORE INSERT OR UPDATE OR DELETE ON "quotation_lines"
  FOR EACH ROW EXECUTE FUNCTION "quotation_lines_guard"();

-- Repair history and notes are append-only, like the audit log.
CREATE FUNCTION "repair_records_block_mutation"() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION '% is append-only', TG_TABLE_NAME;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER "repair_status_history_no_update_delete"
  BEFORE UPDATE OR DELETE ON "repair_status_history"
  FOR EACH ROW EXECUTE FUNCTION "repair_records_block_mutation"();

CREATE TRIGGER "repair_notes_no_update_delete"
  BEFORE UPDATE OR DELETE ON "repair_notes"
  FOR EACH ROW EXECUTE FUNCTION "repair_records_block_mutation"();
